/**
 *
 * TabsContent is the scrollable viewport container for tabs.
 *
 * [Live Demo](https://www.primereact.org/tabs/)
 *
 * @module TabsContent
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { TabsRootInstance } from './TabsRoot.types';
/**
 * Defines passthrough(pt) options type in TabsContent component.
 */
export type TabsContentPassThroughType<E> = PassThroughType<TabsContentInstance, E>;
/**
 * Defines passthrough(pt) options of TabsContent component.
 */
export interface TabsContentPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: TabsContentPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in TabsContent component.
 */
export interface TabsContentProps extends BaseComponentProps<TabsContentInstance, unknown, TabsContentPassThrough> {
}
/**
 * Defines valid state in TabsContent component.
 */
export interface TabsContentState {
}
/**
 * Defines the methods and properties exposed by TabsContent component.
 */
export interface TabsContentExposes {
    /**
     * The Tabs component instance.
     */
    tabs: TabsRootInstance | undefined | null;
}
/**
 * Instance of TabsContent component.
 */
export type TabsContentInstance = ComponentInstance<TabsContentProps, TabsContentState, TabsContentExposes>;
